'use strict';
const canvas=document.getElementById('world-canvas'),ctx=canvas.getContext('2d');
const stops=[{x:-140,y:-90,title:'01 / HELLO',text:'你好，我是孔德曦。很高兴认识你。',label:'你好',color:'#ff633b'},{x:145,y:-95,title:'02 / NICE TO MEET YOU',text:'世界很大，能在这里遇见，就很巧。',label:'相遇',color:'#779b6e'},{x:80,y:150,title:'03 / SAY HELLO',text:'想聊聊？给我打个电话：13243503433。',label:'联系',color:'#e8b646'}];
const car={x:0,y:25,angle:-Math.PI/2,speed:0},keys=new Set(),seen=new Set();let w=0,h=0,scale=1,last=0,activeStop=-1,raf=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(w/800,(h-90)/450);draw();}
function iso(x,y,z=0){return{x:w/2+(x-y)*.84*scale,y:h*.55+(x+y)*.43*scale-z*scale};}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>(i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function box(x,y,sx,sy,z,top,front,side){const a=iso(x,y,z),b=iso(x+sx,y,z),c=iso(x+sx,y+sy,z),d=iso(x,y+sy,z);poly([d,c,iso(x+sx,y+sy),iso(x,y+sy)],front);poly([b,c,iso(x+sx,y+sy),iso(x+sx,y)],side);poly([a,b,c,d],top);}
function circle(x,y,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}
function tree(x,y,size=1){const p=iso(x,y);ctx.save();ctx.translate(p.x,p.y);ctx.scale(scale*size,scale*size);ctx.fillStyle='#756e5b22';ctx.beginPath();ctx.ellipse(12,5,23,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#766347';ctx.fillRect(-3,-35,6,38);circle(0,-43,20,'#637b54');circle(-8,-54,16,'#7c9567');circle(8,-55,14,'#8da274');ctx.restore();}
function sign(s,index){const p=iso(s.x,s.y),near=activeStop===index;ctx.save();ctx.translate(p.x,p.y);ctx.scale(scale,scale);ctx.strokeStyle=near?s.color:'#a9a28b';ctx.lineWidth=near?2:1;ctx.beginPath();ctx.ellipse(0,3,52,26,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#5f594a';ctx.fillRect(-2,-65,4,66);ctx.fillStyle=s.color;ctx.fillRect(-30,-83,60,30);ctx.fillStyle='#22231f';ctx.font='bold 13px Arial,"PingFang SC",sans-serif';ctx.textAlign='center';ctx.fillText(s.label,0,-63);if(seen.has(index)){ctx.fillStyle='#292b23';ctx.font='12px Arial';ctx.fillText('✓',38,-64);}ctx.restore();}
function drawCar(){const p=iso(car.x,car.y);ctx.save();ctx.translate(p.x,p.y);ctx.scale(scale,scale*.61);ctx.rotate(car.angle+Math.PI/4);ctx.fillStyle='#3d382b33';ctx.beginPath();ctx.ellipse(4,7,25,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252722';[[-13,-14],[7,-14],[-13,8],[7,8]].forEach(([x,y])=>ctx.fillRect(x,y,8,7));ctx.fillStyle='#bb4129';ctx.fillRect(-18,-11,40,25);ctx.fillStyle='#ff683e';ctx.fillRect(-18,-17,40,25);ctx.fillStyle='#ff9977';ctx.fillRect(-8,-14,16,20);ctx.fillStyle='#374d4d';ctx.fillRect(5,-12,5,15);ctx.fillStyle='#243a3d';ctx.fillRect(-9,-12,5,15);ctx.fillStyle='#fff2b5';ctx.fillRect(18,-13,4,5);ctx.fillRect(18,1,4,5);ctx.restore();}
function draw(){ctx.clearRect(0,0,w,h);ctx.fillStyle='#e4dfcf';ctx.fillRect(0,0,w,h);poly([iso(-295,-260),iso(295,-260),iso(295,260),iso(-295,260)],'#c8c8a9');poly([iso(-295,260),iso(295,260),iso(295,260,-17),iso(-295,260,-17)],'#aaa88c');poly([iso(295,-260),iso(295,260),iso(295,260,-17),iso(295,-260,-17)],'#96977e');
ctx.lineWidth=.6;for(let n=-280;n<295;n+=35){poly([iso(n,-260),iso(n,260)],null,'#b8b99b');poly([iso(-295,n),iso(295,n)],null,'#b8b99b');}
poly([iso(-270,-36),iso(270,-36),iso(270,35),iso(-270,35)],'#b5ae98');poly([iso(-35,-235),iso(35,-235),iso(35,235),iso(-35,235)],'#b5ae98');
ctx.strokeStyle='#ded8c3';ctx.lineWidth=2*scale;ctx.setLineDash([10*scale,13*scale]);let a=iso(-270,0),b=iso(270,0);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();a=iso(0,-235);b=iso(0,235);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);
box(-230,-180,70,65,48,'#f3ecd9','#d6cbb0','#bfb296');box(-220,-170,50,45,62,'#ff8153','#d95e37','#b64a2c');
const items=[...stops.map((s,i)=>({depth:s.x+s.y,draw:()=>sign(s,i)})),...([[-230,90,1.2],[-205,160,1],[-90,-210,1.1],[100,-200,1.2],[220,95,1.2],[205,165,.9],[-220,-60,.8]]).map(([x,y,s])=>({depth:x+y,draw:()=>tree(x,y,s)})),{depth:car.x+car.y,draw:drawCar}];items.sort((a,b)=>a.depth-b.depth).forEach(o=>o.draw());
const marker=iso(-195,-135,77);ctx.fillStyle='#332e26';ctx.font=`bold ${13*scale}px Arial`;ctx.textAlign='center';ctx.fillText('KDX',marker.x,marker.y);
box(165,-195,32,30,20,'#e4b85e','#b5934a','#aa8642');box(200,-158,22,22,15,'#f0dc9d','#c6ae77','#a58f64');
}
function visit(i){activeStop=i;seen.add(i);document.querySelector('#scene-message span').textContent=stops[i].title;document.querySelector('#scene-message strong').textContent=stops[i].text;document.getElementById('scene-count').textContent=`已发现 ${seen.size} / 3 个路标`;document.querySelector(`[data-stop="${i}"]`).classList.add('visited');}
function frame(now){const dt=Math.min((now-last)/1000||0,.04);last=now;let dx=0,dy=0;if(keys.has('up')){dx-=1;dy-=1}if(keys.has('down')){dx+=1;dy+=1}if(keys.has('left')){dx-=1;dy+=1}if(keys.has('right')){dx+=1;dy-=1}if(dx||dy){const n=Math.hypot(dx,dy);car.x=Math.max(-263,Math.min(263,car.x+dx/n*135*dt));car.y=Math.max(-225,Math.min(225,car.y+dy/n*135*dt));car.angle=Math.atan2(dy,dx);let near=stops.findIndex(s=>Math.hypot(s.x-car.x,s.y-car.y)<62);if(near>=0&&near!==activeStop)visit(near);draw();}raf=requestAnimationFrame(frame);}
const mapping={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};
canvas.addEventListener('keydown',e=>{if(mapping[e.key]){e.preventDefault();keys.add(mapping[e.key]);}});window.addEventListener('keyup',e=>keys.delete(mapping[e.key]));window.addEventListener('blur',()=>keys.clear());canvas.addEventListener('blur',()=>keys.clear());
for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.move);b.classList.add('active');});const release=()=>{keys.delete(b.dataset.move);b.classList.remove('active')};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);b.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();keys.add(b.dataset.move)}});b.addEventListener('keyup',release);b.addEventListener('blur',release);}
for(const b of document.querySelectorAll('[data-stop]'))b.addEventListener('click',()=>{let i=+b.dataset.stop;car.x=stops[i].x+38;car.y=stops[i].y+30;keys.clear();visit(i);draw();});
canvas.addEventListener('click',e=>{canvas.focus({preventScroll:true});const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const i=stops.findIndex(s=>{const p=iso(s.x,s.y,60);return Math.hypot(p.x-x,p.y-y)<45*scale});if(i>=0){car.x=stops[i].x+38;car.y=stops[i].y+30;visit(i);draw();}});
document.getElementById('reset').addEventListener('click',()=>{keys.clear();Object.assign(car,{x:0,y:25,angle:-Math.PI/2});activeStop=-1;seen.clear();document.querySelectorAll('[data-stop]').forEach(b=>b.classList.remove('visited'));document.querySelector('#scene-message span').textContent='WELCOME TO MY WORLD';document.querySelector('#scene-message strong').textContent='你好，朋友。欢迎来兜风！';document.getElementById('scene-count').textContent='已发现 0 / 3 个路标';draw();});
document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('copy').addEventListener('click',async()=>{const t=document.getElementById('toast');try{await navigator.clipboard.writeText('13243503433');t.textContent='电话号码已复制';}catch{t.textContent='请长按号码复制：13243503433'}t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3000);});
new ResizeObserver(resize).observe(canvas);resize();raf=requestAnimationFrame(frame);
document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden){cancelAnimationFrame(raf)}else{last=0;raf=requestAnimationFrame(frame)}});
